    # 2 bordadura + 7 tunel unico
    tun = [r for r in range(R) if g[r][0] == 0 or g[r][-1] == 0]
    assert len(tun) == 1, tun
    T = tun[0]
    assert not (15 <= T <= 18)
    for r in [0, 35]:
        row = g[r]
        assert set(row) == {1}
    for r in range(1, 35):
        assert g[r][0] in (0,1) and g[r][1] in (0,1)
        for c in (0, C-1):
            assert g[r][c] == 0 and r == T
    # 6 castrum
    for r in range(15, 19):
        for c in range(11, 17):
            assert g[r][c] == 1
    for r in (14, 19):
        for c in range(11, 17):
            assert g[r][c] == 0
    for r in range(15, 19):
        assert g[r][10] == 0 and g[r][17] == 0
    # 4 + 5 com wrap no tunel
    def nb(r, c):
        out = []
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if nr < 0 or nr >= R: continue
            if nc < 0:   nc = C-1 if r == T else None
            elif nc >= C: nc = 0 if r == T else None
            if nc is not None: out.append((nr, nc))
        return out
    pass_ = {(r,c) for r in range(R) for c in range(C) if g[r][c]==0}
