    start = next(iter(pass_)); seen = {start}; st = [start]
    while st:
        p = st.pop()
        for q in nb(*p):
            if q in pass_ and q not in seen:
                seen.add(q); st.append(q)
    assert seen == pass_
    # 8 densidade
    f = len(pass_) / 1008
    assert 0.35 <= f <= 0.60, f
    # 9 determinismo/distincao
    assert g == maze.generate_maze(maze_seed_holder[0])
    return f

for seed in range(3000):
    f = check(maze.generate_maze(seed))
